package render

import (
	"regexp"
	"sort"
	"strings"

	"github.com/alecthomas/chroma/v2/formatters/html"
	"github.com/alecthomas/chroma/v2/styles"
)

var (
	formatter  = html.New(html.WithClasses(true), html.ClassPrefix(HighlightClassPrefix))
	styleLight = styles.Get("github")
	styleDark  = styles.Get("github-dark")
)

// HighlightCSS returns the stylesheet for Markdown's highlight classes, generated by
// chroma's html.Formatter.WriteCSS with HighlightClassPrefix, all scoped under .hl-chroma.
// It is a light style followed by a dark style wrapped in @media (prefers-color-scheme: dark).
// The output is deterministic.
func HighlightCSS() string {
	var light, dark strings.Builder
	if err := formatter.WriteCSS(&light, styleLight); err != nil {
		panic(err)
	}
	if err := formatter.WriteCSS(&dark, styleDark); err != nil {
		panic(err)
	}
	// A token the dark style leaves unset would keep the light colour on a dark background.
	darkSelectors := selectors(dark.String())
	var missing []string
	for sel := range selectors(light.String()) {
		if !darkSelectors[sel] {
			missing = append(missing, sel)
		}
	}
	sort.Strings(missing)
	var sb strings.Builder
	sb.WriteString(light.String())
	sb.WriteString("@media (prefers-color-scheme: dark) {\n")
	sb.WriteString(dark.String())
	for _, sel := range missing {
		sb.WriteString(sel + " { color: inherit; background-color: transparent }\n")
	}
	sb.WriteString("}\n")
	return sb.String()
}

var ruleSelectorRe = regexp.MustCompile(`(?m)^(?:/\*.*\*/ )?([^{\n]+?) \{`)

func selectors(css string) map[string]bool {
	set := map[string]bool{}
	for _, m := range ruleSelectorRe.FindAllStringSubmatch(css, -1) {
		set[m[1]] = true
	}
	return set
}
